{
  "root_cause": "The offcanvas focus trap is only activated when the scroll option is false. When data-bs-scroll=\"true\" is set, the focus trap is not activated, allowing focus to escape the offcanvas when tabbing.",
  "repair_strategy": "Activate the focus trap unconditionally in the offcanvas shown callback, while keeping the scroll-dependent scrollbar hiding behavior unchanged.",
  "expected_accessibility_effect": "Focus will remain trapped inside the offcanvas when tabbing, enabling keyboard users to navigate the help panel without moving focus to underlying page controls.",
  "functional_risks": [
    "Offcanvas instances that intentionally use scroll:true and expect no focus trap (e.g., non-modal sidebars) may now trap focus, potentially altering their intended behavior."
  ],
  "verification_requirements": [
    "Verify that opening the offcanvas with data-bs-scroll=\"true\" and pressing Tab keeps focus inside the offcanvas and does not move focus to page elements.",
    "Verify that closing the offcanvas restores focus to the trigger button.",
    "Verify that offcanvas instances with scroll:false continue to work as before (focus trap active, scrollbar hidden)."
  ]
}
